{
  "concepts": [
    {
      "conditions": [],
      "definition": "F11 is the source's foundation-to-law family for change entry, classification and reuse, ambiguity governance and shared-interface migration. Its additional instance premises are changing specifications during work, reports of every kind arriving at one product, shared interfaces with several producers and consumers, and decisions either permitted under policy or reserved to human authority. The cited standing is P0 recovered; P1, P2, P3, P4a and P6 independent; P4b derived from P0 and P2 with non-reacquirable step-produced facts; P5 derived from P0 and P6 with the open-world premise.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 788,
          "quote": "Standing of\n the commitments cited",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FFoundation%20to%20law%3A%20change%20management%20and%20ambiguity",
          "start_line": 784
        }
      ],
      "key": "change_governance_family",
      "label": "Change management and ambiguity foundation family"
    },
    {
      "conditions": ["A report may represent substantive change."],
      "definition": "Universal intake triage is the common entry for bugs, feature requests, issues, regressions, operator findings, release blockers and scenario failures. It determines substantive-change status, affected product and scope, lawful change class, lawful constitutional re-entry, affected downstream surfaces and evidence, and release-scope fit or repricing.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 830,
          "quote": "There is one front door for substantive change. The intake label does not\n determine the process class:",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FUniversal%20intake%20triage",
          "start_line": 827
        }
      ],
      "key": "intake_triage",
      "label": "Universal intake triage"
    },
    {
      "conditions": [],
      "definition": "The minimum declared change states are: goal_reprice, changing bounded work-wave focus, re-entering Goals and flowing through Intent, Product, Requirements, Design, Code and Evidence where that focus changes deeper truth; intent_reprice, directional or scope change, re-entering Intent and flowing through Product, Requirements, Design, Code and Evidence; product_reprice, changed current product realisation with stable directional intent, re-entering Product and flowing through Requirements, Design, Code and Evidence; requirement_reprice, changed constitutional truth with stable project direction, re-entering Requirements and flowing through Design, Code and Evidence; design_reframe, changed realisation structure with stable active intent and requirement truth, re-entering Design and flowing through Code and Evidence; realization_refactor, local code, configuration or attribute change without intended constitutional or structural change, re-entering only the realised surface with no upstream flow and requiring proof of no upstream drift.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 888,
          "quote": "| `realization_refactor` | local code, configuration or attribute change with no intended constitutional or structural change | the realised surface only | nothing upstream; it must prove no upstream drift |",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FChange%20classes",
          "start_line": 888
        }
      ],
      "key": "change_classes",
      "label": "Declared change classes and flows"
    },
    {
      "conditions": [],
      "definition": "C denotes reproducible facts and declared-rule application in one reusable intake classification. Relation states changed, unchanged and unknown; identity changes added, removed or retained with changed value; and evidence states covered, missing, stale, ambiguous and outside scope are classification facts, not evaluation results or core values.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 918,
          "quote": "C denotes reproducible facts and declared rule\napplication; J denotes residual semantic or materiality judgment; O denotes\na ruling reserved to its actual owner.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FComputed%20classification%20and%20treatment",
          "start_line": 916
        }
      ],
      "key": "computed_classification",
      "label": "Computed classification C"
    },
    {
      "conditions": ["Semantic sufficiency, materiality, intended meaning or necessity remains unresolved by sufficient declared premises."],
      "definition": "J is residual semantic or materiality judgment, kept distinct from reproducible classification facts and owner-reserved rulings. No residual judgment is invented when declared rules settle the question.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 918,
          "quote": "J denotes residual semantic or materiality judgment;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FComputed%20classification%20and%20treatment",
          "start_line": 917
        }
      ],
      "key": "semantic_judgment",
      "label": "Residual judgment J"
    },
    {
      "conditions": ["A decision is reserved to its actual owner."],
      "definition": "O denotes an owner-reserved ruling. C, J and O annotations grant no authority and introduce no calculus kind, runtime, classifier interface or mandatory document.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 922,
          "quote": "The annotations grant no authority,",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FComputed%20classification%20and%20treatment",
          "start_line": 918
        }
      ],
      "key": "owner_ruling",
      "label": "Owner ruling O"
    },
    {
      "conditions": ["A declared change span is under assessment."],
      "definition": "The consistency gate applies the TICKETS-owned condition-based closure rule to obligations declared for the change span, requiring upstream sufficiency, downstream consistency with active truth, and proof of active intended behaviour.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1034,
          "quote": "its required coverage.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FConsistency%20gate",
          "start_line": 1034
        }
      ],
      "key": "consistency_gate",
      "label": "Consistency gate"
    },
    {
      "conditions": [],
      "definition": "A sprint is a bounded execution-control surface under existing goals, intent, product, requirement and design authority. It batches and coordinates work, prices proof cost and forces close review without adding a constitutional layer.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1054,
          "quote": "A sprint is a bounded execution-control surface, not a new layer in the\nconstitutional chain",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FSprint%20execution%20boundary",
          "start_line": 1053
        }
      ],
      "key": "sprint_boundary",
      "label": "Method sprint boundary"
    },
    {
      "conditions": [],
      "definition": "Work-carrier selection follows required lifetime: a durable ticket for identity across sessions, a sprint-local entry for traceability whose only value is inside the batch, or a run/return record for work confined to one activation. TICKETS owns the carrier model and smallest-lawful-carrier selection.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1101,
          "quote": "The carrier of a work item is selected for its required lifetime:",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FCarriers",
          "start_line": 1098
        }
      ],
      "key": "carrier_selection",
      "label": "Lifetime-based carrier selection"
    },
    {
      "conditions": [],
      "definition": "Four source-defined procedures cover substantive intake, feature introduction/change, project bootstrap or requirement-surface repricing, and gaps revealed by real use cases. Their ordering, conditional updates and design acceptance boundaries are represented as requirements rather than executed procedures.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1115,
          "quote": "only then treat the work as implementation, repricing or\nrelease-bound change.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F4.%20Change%20management%2FProcedures",
          "start_line": 1114
        }
      ],
      "key": "change_procedures",
      "label": "Change-management procedures"
    },
    {
      "conditions": ["Under the selected complete basis."],
      "definition": "The substrate-neutral context urn:stdo:bounded-context:ambiguity-governance governs progressive disambiguation. Goals narrow priority and work-wave focus; intent direction and scope; product realisation shape and terms; requirements constitutional obligation; tenant/stack choice executable realisation class; design structural interpretation; implementation local detail. Major ambiguity materially affects architecture, stack, product boundary, execution/deployment admissibility, public contract or downstream law; micro ambiguity is a local choice within an already-governed design boundary.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1186,
          "quote": "`urn:stdo:bounded-context:ambiguity-governance`",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F5.%20Ambiguity%20governance%20and%20lifecycle",
          "start_line": 1183
        }
      ],
      "key": "ambiguity_governance",
      "label": "Ambiguity governance"
    },
    {
      "conditions": ["Declared policy permits bounded processing to carry or resolve declared ambiguity."],
      "definition": "urn:stdo:concept:ambiguity-governance:lawful-probabilistic-processing names bounded non-human processing permitted by policy. A person carrying or deciding ambiguity under policy without human-adjudication admission is governed by this processing's policy and recording requirements; performer identity does not determine operation kind.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1219,
          "quote": "is bounded non-human processing permitted by declared policy to carry or\nresolve declared ambiguity.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F5.%20Ambiguity%20governance%20and%20lifecycle",
          "start_line": 1218
        }
      ],
      "key": "probabilistic_processing",
      "label": "Lawful probabilistic processing"
    },
    {
      "conditions": ["Authority admits explicit human judgment to resolve declared ambiguity where policy or risk appetite requires it."],
      "definition": "urn:stdo:concept:ambiguity-governance:human-adjudication names explicitly admitted human judgment. Admission makes the operation adjudication; merely relaying, recording or performing a step does not.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1224,
          "quote": "That admission makes an operation\nhuman adjudication.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F5.%20Ambiguity%20governance%20and%20lifecycle",
          "start_line": 1222
        }
      ],
      "key": "human_adjudication",
      "label": "Human adjudication"
    },
    {
      "conditions": [],
      "definition": "Recursive product lineage distinguishes substrate, development product, source project, release cut, product, install, artifact and product definition. The product definition is the source project's present-tense surface, distinct from the released artifact and active builder. Immutable v<version>-rc.<n> identifies an exact release cut; mutable v<version> discovers the highest-ordinal published cut. Calculus, subject interpretation and carrier encoding maintain independent content identities, judgments, supersession and proof obligations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1261,
          "quote": "The only exact operative release identifier is the immutable release-cut\ntag `v<version>-rc.<n>`",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F6.%20Lineage%20and%20release",
          "start_line": 1260
        }
      ],
      "key": "lineage_release",
      "label": "Product lineage and release identities"
    },
    {
      "conditions": ["A reusable method change is proposed."],
      "definition": "Shared-method adoption expresses authority causality in this order: incident/review evidence, shared-method intake, one owning standard, consistency and independent review, human-authority acceptance, one complete released STDO version, explicit consumer selection, and consumer-owned realisation/evidence. It prescribes neither an intake workflow nor an artifact set.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1310,
          "quote": "The chain states authority causality. It prescribes no intake workflow and\nno artifact set",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F6.%20Lineage%20and%20release%2FShared%20method%20adoption%20and%20propagation%20%28STDO-UP-012%29",
          "start_line": 1309
        }
      ],
      "key": "method_adoption",
      "label": "Shared method adoption and propagation"
    },
    {
      "conditions": ["A shared contract or carrier materially governs one or more listed truth-bearing functions."],
      "definition": "A core interface materially governs runtime closure, reporting/status truth, topology/frame progression, proof/qualification outcomes, event/projection semantics, identity/binding resolution, or provider/resolver behaviour. A change capable of altering how multiple surfaces determine present truth is a core-interface change.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1420,
          "quote": "If changing the\ninterface can alter how multiple surfaces decide what is true now, it is a\ncore interface change",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FWhat%20counts%20as%20a%20core%20interface",
          "start_line": 1418
        }
      ],
      "key": "core_interface",
      "label": "Core interface"
    },
    {
      "conditions": ["A change alters a load-bearing contract, carrier, resolver, provider, projection law, closure law or other interface shared by multiple surfaces."],
      "definition": "Core-interface migration is constitutional migration rather than an ordinary local patch. It replaces authoritative contract truth, migrates every impacted producer and consumer, and follows downstream effects until superseded closure law is gone.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1326,
          "quote": "the work is handled as a constitutional migration, not as incremental\npatching",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FCore%20interface%20migration",
          "start_line": 1325
        }
      ],
      "key": "core_migration",
      "label": "Constitutional core-interface migration"
    },
    {
      "conditions": ["The project stays on the same implementation line and replaces authoritative source truth in place."],
      "definition": "Inside-out hard-break migration is one of two lawful constitutional strategies. It proceeds from the source carrier outward through deliberate breaks and repairs; bounded evolution is a rebuttable strategy-selection presumption, not a third strategy.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1349,
          "quote": "Inside-out hard-break migration applies when the project remains on the\nsame implementation line and the authoritative source truth is being\nreplaced in place;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FConstitutional%20migration%20options",
          "start_line": 1346
        }
      ],
      "key": "inside_out_migration",
      "label": "Inside-out hard-break strategy"
    },
    {
      "conditions": ["A project intentionally abandons prior constitutional shape and re-derives on a new branch, version line or methodology basis."],
      "definition": "Fundamental migration is a constitutional reset. Fundamental re-adoption applies to a major rewrite on a materially different implementation basis, such as runtime, carrier, type system, substrate or realisation tree; prior implementation becomes reference material. Inherited constitutional material has adoption states adopted, superseded, deferred or orphaned. Inherited implementation is carry_across, materially unchanged and explicitly re-adopted; redundant, no longer needed; or rewrite, still needed but rebuilt under new requirements and design.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1544,
          "quote": "A fundamental migration is a constitutional reset, not an in-place\nrefactor.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FFundamental%20migration",
          "start_line": 1541
        },
        {
          "end_line": 1354,
          "quote": "the prior implementation is moved sideways\nand treated as reference material, not live authority.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FConstitutional%20migration%20options",
          "start_line": 1353
        }
      ],
      "key": "fundamental_migration",
      "label": "Fundamental migration and re-adoption"
    },
    {
      "conditions": ["An affected product outcome is considered for promotion."],
      "definition": "The acceptance path is the outcome's full causal closure: every admitted entrypoint, producer, consumer, resolver, fallback, shared state surface, event, projection and proof surface capable of changing, interpreting or closing it. Singular authority concerns this entire closure, not one successful trace.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1393,
          "quote": "Singular authority means\none governing authority across that closure, not one selected successful\ntrace.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FConstitutional%20migration%20options",
          "start_line": 1391
        }
      ],
      "key": "acceptance_path",
      "label": "Outcome acceptance path"
    },
    {
      "conditions": ["An intermediate product outcome is considered within an open migration."],
      "definition": "A product slice has identity and acceptance criteria derived from the product, every causally applicable live requirement, accepted design relation and retained predecessor claim. Slice promotion is distinct from migration, qualification or release closure.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1404,
          "quote": "The slice's identity and acceptance criteria derive\nfrom the product plus every causally applicable live requirement, accepted\ndesign relation and retained predecessor claim;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FConstitutional%20migration%20options",
          "start_line": 1402
        }
      ],
      "key": "product_slice",
      "label": "Intermediate product slice"
    },
    {
      "conditions": [],
      "definition": "Projections, reports, status views and topology views reflect an authoritative carrier while remaining downstream of its truth and closure law.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1454,
          "quote": "Projections, reports, status views and topology views may reflect the\nauthoritative carrier; they do not become a second closure surface",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FProjection%20discipline",
          "start_line": 1452
        }
      ],
      "key": "migration_projection",
      "label": "Downstream projection"
    },
    {
      "conditions": ["Refactor or migration affects mutable implementation surfaces."],
      "definition": "A transformation wave is the changing implementation across its declared affected scope. An inside-out migration wave is an ordered set of hard breaks over one interface family, not a mode permitting competing authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1615,
          "quote": "Refactor and migration should be understood as a transformation wave over\nmutable\nimplementation surfaces",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FTransformation%20wave",
          "start_line": 1613
        },
        {
          "end_line": 1482,
          "quote": "The migration wave is the ordered set of those breaks;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FHard-break%20discipline",
          "start_line": 1481
        }
      ],
      "key": "transformation_wave",
      "label": "Transformation and migration wave"
    },
    {
      "conditions": ["Construction is delegated to a probabilistic or agentic worker."],
      "definition": "Bounded execution applies ACTIVATION's step: accepted governing basis, bounded affected relations, selected computational relations, delegated execution and decision grants, construction/self-review, required independent live-surface assessment, owner disposition accept/local_repair/re_enter/reject, exact accepted checkpoint, and next already-authorised bounded action. Candidate availability, assessment results and owner disposition are separate results; preservation, progress and completion are distinct construction claims.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1658,
          "quote": "a candidate that is available or\nassessed is not thereby accepted",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F8.%20Bounded%20execution%20in%20this%20method",
          "start_line": 1657
        }
      ],
      "key": "bounded_execution",
      "label": "Bounded construction step"
    },
    {
      "conditions": ["A realisation claim requires closure evidence."],
      "definition": "Realisation evidence includes an authority trace, realisation proof, negative proof where drift is plausible, and a present-tense statement of residual open pressure. This is an application of the TICKETS closure condition, not an additional closure condition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1724,
          "quote": "requires includes an authority trace, realisation proof, negative proof\nwhere drift is plausible, and a present-tense statement of the residual\nopen pressure;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F9.%20Evidence",
          "start_line": 1722
        }
      ],
      "key": "realisation_evidence",
      "label": "Evidence for a realisation claim"
    },
    {
      "conditions": [],
      "definition": "An ADR records a design decision boundary answering what design choice makes the acceptance criteria true. Each ADR file remains constitutional source; an optional registry is a read model. ADR history is append-only subject to explicit retirement.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1740,
          "quote": "ADRs are written per decision boundary, not per requirement file;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F10.%20Design%20records",
          "start_line": 1738
        }
      ],
      "key": "design_record",
      "label": "Architecture decision record"
    },
    {
      "conditions": ["Every product built with the described method."],
      "definition": "A build tenant is an independent project-owned HOW realisation of a product's WHAT. One WHAT has one or more independent tenants regardless of physical layout. A registry entry locates the tenant and is not its binding; tenant-local realisation remains derivative until governing truth is ratified in specification.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1794,
          "quote": "A build tenant is one independent, project-owned HOW realisation of a\n  product's WHAT.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F11.%20Build-tenant%20binding",
          "start_line": 1791
        }
      ],
      "key": "build_tenant",
      "label": "Build tenant"
    },
    {
      "conditions": [],
      "definition": "A product's requirements calculus comprises its WHAT obligations, permitted outcomes, and rules for refining and composing the work that realises it.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1797,
          "quote": "The requirements calculus of a product is the set of obligations its\n  WHAT states, the outcomes it permits, and its rules for refining and\n  composing the work that realises it.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F11.%20Build-tenant%20binding",
          "start_line": 1795
        }
      ],
      "key": "requirements_calculus",
      "label": "Requirements calculus"
    },
